INSERT INTO `product` (`pd_id`, `pd_name`, `pd_price`, `pd_description`, `pdt_id`, `pd_image`, `pd_last_update`) VALUES
(1, 'Phô mai chocolate hạt điều', 95000, 'Bánh trung thu Phô Mai Chocolate – Hạt Điều được làm từ những nguyên liệu tự nhiên tươi ngon cao cấp, chọn lọc kỹ lưỡng. Vỏ bánh mềm mịn, mang màu sắc và hương vị đặc trưng của chocolate. Nhân bánh là sự hòa quyện hoàn hảo giữa phô mai béo ngậy, chocolate đậm đà và hạt điều bùi thơm, tạo nên một trải nghiệm ẩm thực độc đáo và hấp dẫn.', 1, , '2025-11-14 10:52:58');
INSERT INTO `product` (`pd_id`, `pd_name`, `pd_price`, `pd_description`, `pdt_id`, `pd_image`, `pd_last_update`) VALUES
(2, 'Phô mai dưa lưới hạt chia', 95000, 'Bánh trung thu Phô Mai Dưa Lưới – Hạt Chia là sự kết hợp hoàn hảo giữa lớp vỏ bánh mềm mịn và nhân bánh độc đáo. Thành phần bao gồm bột mì, trứng gà, phô mai béo ngậy, dưa lưới thơm ngọt và hạt chia giàu dinh dưỡng.', 1, , '2025-11-14 10:52:58');
INSERT INTO `product` (`pd_id`, `pd_name`, `pd_price`, `pd_description`, `pdt_id`, `pd_image`, `pd_last_update`) VALUES
(3, 'Lava phô mai hoàng kim', 105000, 'Bánh Trung Thu Phô Mai Hoàng Kim chinh phục thực khách bởi sự kết hợp hoàn hảo giữa những nguyên liệu cao cấp, tạo nên hương vị độc đáo và sang trọng khó cưỡng. Nhân bánh là sự hòa quyện tuyệt vời của phô mai mềm mịn, béo ngậy cùng vị ngọt thanh tao, mang đến trải nghiệm vị giác bùng nổ. Vỏ bánh than tre không chỉ tạo nên màu sắc mới lạ mà còn mang đến cảm giác thanh nhẹ, bổ dưỡng cho sức khỏe.', 1, , '2025-11-14 10:52:58');
